package com.hengaikj.ai.controller;
import com.hengaikj.ai.entity.*; import com.hengaikj.ai.service.ApiKeyService; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.util.*;
@RestController @RequestMapping("/api") public class ApiKeyController { private final ApiKeyService service; public ApiKeyController(ApiKeyService s){service=s;}
 @PostMapping("/projects/{projectId}/api-keys") public ResponseEntity<ApiKeyCreateResponse> create(@PathVariable long projectId,@RequestHeader("X-Enterprise-Id") long enterprise,@RequestBody ApiKeyCreateRequest req){return ResponseEntity.status(201).body(service.create(enterprise,projectId,req));}
 @GetMapping("/projects/{projectId}/api-keys") public List<ApiKeySummary> list(@PathVariable long projectId,@RequestHeader("X-Enterprise-Id") long enterprise){return service.list(enterprise,projectId);}
 @PostMapping("/api-keys/{keyId}/{action}") public ApiKeySummary change(@PathVariable long keyId,@PathVariable String action,@RequestHeader("X-Enterprise-Id") long enterprise,@RequestParam long projectId){String status=switch(action){case "enable"->"ENABLED";case "disable"->"DISABLED";case "revoke"->"REVOKED";default->throw new IllegalArgumentException("不支持的状态操作");};return service.change(enterprise,projectId,keyId,status);}
 @GetMapping("/api-keys/verify") public ResponseEntity<?> verify(@RequestHeader(required=false) String authorization,@RequestParam long enterpriseId,@RequestParam long projectId){if(authorization==null||!authorization.startsWith("Bearer "))return ResponseEntity.status(401).build();ApiKeyEntity e=service.findActive(authorization.substring(7),enterpriseId,projectId);return e==null?ResponseEntity.status(401).build():ResponseEntity.ok(new ApiKeySummary(e.id,e.keyName,e.keyPrefix,e.status,e.expiresAt,e.createdAt));}}
